        raise LedgerError("unknown card")
    if sender == recipient:
        raise LedgerError("cannot send to the same card")
    cents = int(amount)
    if cents < 0:
        raise LedgerError("negative amount not allowed")
    remaining = ledger[sender] - cents
    if remaining < 0:
        raise LedgerError("not enough balance")
    ledger[recipient] += cents
    if ledger[recipient] > MAX_BALANCE_CENTS:
        raise LedgerError("recipient would exceed maximum balance")
    ledger[sender] = remaining
    return remaining

